window.HOEREN_TESTS[90] = {"id":"in-der-apotheke","name":"In der Apotheke","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Guten Tag, hier ist die Stadt-Apotheke. Ihr Medikament ist da — aber nicht in Tablettenform, die war aus. Wir haben es als Saft bekommen, das wirkt genauso gut. Sie können es ab 15 Uhr abholen. Bringen Sie bitte das Rezept mit, falls Sie es noch nicht abgegeben haben. Bis später!","gender":"f","q":"In welcher Form ist das Medikament jetzt?","opts":["Als Saft.","Als Tablette.","Als Salbe."],"correct":0},{"transcript":"Hallo Tom, hier ist Markus. Du, ich habe eine starke Erkältung — Husten, Schnupfen, alles. Ich gehe gleich in die Apotheke und hole mir etwas. Brauchst du auch was? Du hast doch gestern auch geniest. Ruf zurück, dann bringe ich dir gleich Hustensaft mit. Gute Besserung uns beiden!","gender":"m","q":"Was hat Markus?","opts":["Kopfschmerzen.","Bauchschmerzen.","Eine Erkältung."],"correct":2},{"transcript":"Achtung Kunden: Bitte beachten Sie unseren Notdienst. Nachts und am Wochenende hat immer eine Apotheke in der Stadt geöffnet. Welche das ist, steht an unserer Tür und im Internet, nicht nur im Krankenhaus und nicht beim Arzt. Für dringende Medikamente fahren Sie bitte dorthin. Wir wünschen gute Besserung und ein schnelles Gesundwerden!","gender":"m","q":"Wo findet man die Notdienst-Apotheke?","opts":["Nur im Krankenhaus.","An der Tür und im Internet.","Beim Arzt."],"correct":1},{"transcript":"Hi Lisa, hier ist Anna. Ich war in der Apotheke wegen meiner Kopfschmerzen. Die Apothekerin hat mir geraten, erst mal mehr Wasser zu trinken und früher schlafen zu gehen, statt gleich Tabletten zu nehmen. Sehr nett von ihr. Schon besser! Trink auch mehr, dir hilft das vielleicht auch. Bis bald!","gender":"f","q":"Was hat die Apothekerin geraten?","opts":["Mehr Wasser zu trinken und früher zu schlafen.","Sofort Tabletten zu nehmen.","Zum Arzt zu gehen."],"correct":0},{"transcript":"Liebe Kunden: Vergessen Sie nicht Ihre Reiseapotheke für den Urlaub. Schmerzmittel, etwas gegen Durchfall und Pflaster gehören in jedes Gepäck, nicht nur Vitamine und nicht nur Sonnencreme. Wir beraten Sie gern, was Sie für Ihr Reiseland brauchen. Manche Medikamente gibt es im Ausland nicht. Kommen Sie rechtzeitig vorbei, bevor Sie fahren!","gender":"f","q":"Was gehört in die Reiseapotheke?","opts":["Nur Vitamine.","Schmerzmittel und Pflaster.","Sonnencreme."],"correct":1}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch. Sie hören den Text einmal. Wer braucht was? Wählen Sie für jede Person einen Buchstaben (a–i).","lines":[{"speaker":"Lukas","gender":"m","text":"Hallo Lisa! Die Apotheke ist noch bis zum Abend offen. Hast du den Zettel aus der Küche?"},{"speaker":"Lisa","gender":"f","text":"Er liegt hier. Fünf Leute sind krank und jeder braucht etwas anderes."},{"speaker":"Lukas","gender":"m","text":"Ich brauche Hustensaft. Seit zwei Nächten huste ich und ich schlafe schlecht."},{"speaker":"Lisa","gender":"f","text":"Der steht links unten. Braucht jemand Nasenspray?"},{"speaker":"Lukas","gender":"m","text":"Nasenspray braucht bei uns keiner."},{"speaker":"Lisa","gender":"f","text":"Ich brauche Schmerztabletten, weil mein Kopf seit heute weh tut."},{"speaker":"Lukas","gender":"m","text":"Nimm die kleine Packung. Tom hat einen roten Fleck am Arm."},{"speaker":"Lisa","gender":"f","text":"Tom braucht eine Salbe. Er soll sie abends auf den Arm tun."},{"speaker":"Lukas","gender":"m","text":"Sie liegt unten im Schrank. Kauft jemand Augentropfen für lange Abende?"},{"speaker":"Lisa","gender":"f","text":"Augentropfen kauft auch keiner."},{"speaker":"Lukas","gender":"m","text":"Sara schneidet oft und dann fehlt etwas im Bad."},{"speaker":"Lisa","gender":"f","text":"Sara braucht Pflaster und Verband. Im Bad liegt nichts mehr davon."},{"speaker":"Lukas","gender":"m","text":"Die sind an der Kasse. Tim isst seit Tagen wenig und ist oft schwach."},{"speaker":"Lisa","gender":"f","text":"Tim braucht Vitamine, weil er zu wenig Obst isst."},{"speaker":"Lukas","gender":"m","text":"Die Packung ist grün."},{"speaker":"Lisa","gender":"f","text":"Ich gehe mit dem Zettel zur Kasse."}],"options":[{"letter":"a","text":"Pflaster und Verband"},{"letter":"b","text":"Nasenspray"},{"letter":"c","text":"Vitamine"},{"letter":"d","text":"Augentropfen"},{"letter":"e","text":"Salbe"},{"letter":"f","text":"Tee gegen Husten"},{"letter":"g","text":"Schmerztabletten"},{"letter":"h","text":"Fieberthermometer"},{"letter":"i","text":"Hustensaft"}],"items":[{"person":"Lukas","correct":"i"},{"person":"Lisa","correct":"g"},{"person":"Tom","correct":"e"},{"person":"Sara","correct":"a"},{"person":"Tim","correct":"c"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Kundin","gender":"f","text":"Ich brauche etwas gegen Halsschmerzen. Lutschtabletten, Spray oder Tee?"},{"speaker":"Apotheker","gender":"m","text":"Lutschtabletten oder Spray wirken schnell. Tee ist angenehm, aber langsamer."},{"speaker":"Kundin","gender":"f","text":"Was wirkt schneller? Die Lutschtabletten, das Spray oder der Tee?"},{"speaker":"Apotheker","gender":"m","text":"Das Spray. Lutschtabletten helfen auch, Tee braucht länger. Das Spray wirkt am schnellsten."},{"speaker":"Kundin","gender":"f","text":"Dann nehme ich das Spray. Danke."}],"q":"Was wirkt schneller?","opts":["Lutschtabletten.","Das Spray.","Tee."],"correct":1},{"lines":[{"speaker":"Mann","gender":"m","text":"Brauche ich für dieses Medikament ein Rezept? Oder reicht Bargeld, oder gar nichts?"},{"speaker":"Apothekerin","gender":"f","text":"Ja, das erste gibt es nur mit Rezept. Bargeld allein reicht nicht, und mit leeren Händen gehen Sie auch nicht."},{"speaker":"Mann","gender":"m","text":"Und etwas Ähnliches ohne Rezept? Also nichts Extra, nur ohne Schein?"},{"speaker":"Apothekerin","gender":"f","text":"Dieses hier ist rezeptfrei. Für das erste brauchen Sie ein Rezept, nicht ohne Rezept und nicht nur mit Bargeld."},{"speaker":"Mann","gender":"m","text":"Verstehe, dann hole ich das Rezept beim Arzt. Danke."}],"q":"Was braucht der Mann für das erste Medikament?","opts":["Nichts.","Bargeld.","Ein Rezept."],"correct":2},{"lines":[{"speaker":"Mutter","gender":"f","text":"Mein Kind hat Fieber. Was kann ich geben? Einmal täglich, oder jede Stunde?"},{"speaker":"Apotheker","gender":"m","text":"Wie alt ist das Kind? Einmal täglich kann zu wenig sein, jede Stunde zu viel."},{"speaker":"Mutter","gender":"f","text":"Drei Jahre. Also wie oft den Saft?"},{"speaker":"Apotheker","gender":"m","text":"Dann diesen Saft, dreimal täglich. Nicht einmal und nicht jede Stunde, dreimal reicht."},{"speaker":"Mutter","gender":"f","text":"Gut, dreimal täglich. Danke."}],"q":"Wie oft soll das Kind den Saft bekommen?","opts":["Einmal täglich.","Dreimal täglich.","Jede Stunde."],"correct":1},{"lines":[{"speaker":"Kunde","gender":"m","text":"Wie soll ich die Tabletten nehmen? Vor dem Essen, ohne Wasser, oder nach dem Essen?"},{"speaker":"Apothekerin","gender":"f","text":"Eine morgens, eine abends. Nicht ohne Wasser, das ist wichtig."},{"speaker":"Kunde","gender":"m","text":"Vor oder nach dem Essen? Ohne Wasser geht nicht, oder?"},{"speaker":"Apothekerin","gender":"f","text":"Nach dem Essen, mit Wasser. Nicht vor dem Essen und nicht ohne Wasser."},{"speaker":"Kunde","gender":"m","text":"Alles klar, nach dem Essen mit Wasser. Danke."}],"q":"Wann soll der Kunde die Tabletten nehmen?","opts":["Nach dem Essen.","Ohne Wasser.","Vor dem Essen."],"correct":0},{"lines":[{"speaker":"Kundin","gender":"f","text":"Ist heute Nacht eine Apotheke offen? Die Stadt-Apotheke, oder keine?"},{"speaker":"Apotheker","gender":"m","text":"Ja, die Bahnhof-Apotheke. Die Stadt-Apotheke hat zu."},{"speaker":"Kundin","gender":"f","text":"Die ganze Nacht? Also nicht die Stadt-Apotheke?"},{"speaker":"Apotheker","gender":"m","text":"Ja, sie hat Notdienst. Offen ist die Bahnhof-Apotheke, nicht die Stadt-Apotheke."},{"speaker":"Kundin","gender":"f","text":"Danke, dann fahre ich zur Bahnhof-Apotheke."}],"q":"Welche Apotheke hat nachts Notdienst?","opts":["Die Bahnhof-Apotheke.","Die Stadt-Apotheke.","Keine."],"correct":0}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Frau Roth, einer Apothekerin. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporter","gender":"m","text":"Frau Roth, warum ist die Apotheke vor Ort wichtig?"},{"speaker":"Roth","gender":"f","text":"Weil wir die Kunden beraten. Im Internet bekommt man keinen Rat. Die Beratung in der Apotheke ist wichtig, das sehe ich jeden Tag."},{"speaker":"Reporter","gender":"m","text":"Kommen die Leute auch ohne Arzt zu Ihnen, bei einer Erkältung zum Beispiel?"},{"speaker":"Roth","gender":"f","text":"Ja, oft. Bei einer leichten Erkältung kann ich gut helfen. Viele kommen zuerst zu uns, das ist in Ordnung."},{"speaker":"Reporter","gender":"m","text":"Und bei starken Schmerzen? Geben Sie dann einfach Tabletten?"},{"speaker":"Roth","gender":"f","text":"Dann schicke ich die Leute zum Arzt. Das ist sicherer. Bei starken Schmerzen ist der Arzt besser als nur eine Tablette hier."},{"speaker":"Reporter","gender":"m","text":"Nehmen die Menschen zu viele Tabletten? Soll man bei jeder Kleinigkeit eine nehmen?"},{"speaker":"Roth","gender":"f","text":"Manche schon. Oft helfen auch Ruhe, Schlaf und viel Wasser. Man soll nicht bei jeder Kleinigkeit eine Tablette nehmen."},{"speaker":"Reporter","gender":"m","text":"Was ist bei Tabletten wichtig? Muss man den Zettel lesen?"},{"speaker":"Roth","gender":"f","text":"Lesen Sie immer den Zettel. Und nehmen Sie nicht mehr als erlaubt. Den Zettel muss man lesen, das ist keine Extra-Arbeit, sondern der beste Schutz für Ihre Gesundheit. Fragen Sie uns, wenn etwas unklar ist."}],"items":[{"q":"Frau Roth findet die Beratung in der Apotheke wichtig.","correct":"ja"},{"q":"Bei starken Schmerzen schickt sie die Leute zum Arzt.","correct":"ja"},{"q":"Sie sagt, man soll bei jeder Kleinigkeit eine Tablette nehmen.","correct":"nein"},{"q":"Oft helfen auch Ruhe, Schlaf und Wasser.","correct":"ja"},{"q":"Sie findet, man muss den Zettel im Medikament nicht lesen.","correct":"nein"}]}]};
